Here is the commit message:
bpf, arm64: Force 8-byte alignment for JIT buffer to prevent
 atomic tearing

struct bpf_plt contains a u64 target field. Currently, the BPF JIT
allocator requests an alignment of 4 bytes (sizeof(u32)) for the JIT
buffer.

Because the base address of the JIT buffer can be 4-byte aligned (e.g.,
ending in 0x4 or 0xc), the relative padding logic in build_plt() fails
to ensure that target lands on an 8-byte boundary.

This leads to two issues:
1. UBSAN reports misaligned-access warnings when dereferencing the
   structure.
2. More critically, target is updated concurrently via WRITE_ONCE() in
   bpf_arch_text_poke() while the JIT'd code executes ldr. On arm64,
   64-bit loads/stores are only guaranteed to be single-copy atomic if
   they are 64-bit aligned. A misaligned target risks a torn read,
   causing the JIT to jump to a corrupted address.

Fix this by increasing the allocation alignment requirement to 8 bytes
(sizeof(u64)) in bpf_jit_binary_pack_alloc(). This anchors the base of
the JIT buffer to an 8-byte boundary, allowing the relative padding math
in build_plt() to correctly align the target field.

Fixes: b2ad54e1533e ("bpf, arm64: Implement bpf_arch_text_poke() for arm64")
Signed-off-by: Fuad Tabba <tabba@google.com>
Acked-by: Will Deacon <will@kernel.org>
Link: https://lore.kernel.org/r/20260226075525.233321-1-tabba@google.com
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

Here is the root cause:
The BPF JIT allocator requested 4-byte alignment for the JIT buffer, but struct bpf_plt contains a u64 target field that requires 8-byte alignment. Because the buffer base could be 4-byte aligned, the relative padding logic in build_plt() failed to align target to 8 bytes, leading to misaligned access. On arm64, 64-bit load/store operations require 8-byte alignment for atomicity; misaligned access can cause torn reads when target is updated concurrently via WRITE_ONCE() while JIT code executes ldr. This results in potential corrupted jump addresses.

Here is the patch:

 struct bpf_prog *bpf_int_jit_compile(struct bpf_prog *prog)
 {
 	int image_size, prog_size, extable_size, extable_align, extable_offset;
 	struct bpf_prog *tmp, *orig_prog = prog;
 	struct bpf_binary_header *header;
 	struct bpf_binary_header *ro_header = NULL;
 	struct arm64_jit_data *jit_data;
 	void __percpu *priv_stack_ptr = NULL;
 	bool was_classic = bpf_prog_was_classic(prog);
 	int priv_stack_alloc_sz;
 	bool tmp_blinded = false;
 	bool extra_pass = false;
 	struct jit_ctx ctx;
 	u8 *image_ptr;
 	u8 *ro_image_ptr;
 	int body_idx;
 	int exentry_idx;

 	if (!prog->jit_requested)
 		return orig_prog;

 	tmp = bpf_jit_blind_constants(prog);
 	/* If blinding was requested and we failed during blinding,
 	 * we must fall back to the interpreter.
 	 */
 	if (IS_ERR(tmp))
 		return orig_prog;
 	if (tmp != prog) {
 		tmp_blinded = true;
 		prog = tmp;
 	}

 	jit_data = prog->aux->jit_data;
 	if (!jit_data) {
 		jit_data = kzalloc_obj(*jit_data);
 		if (!jit_data) {
 			prog = orig_prog;
 			goto out;
 		}
 		prog->aux->jit_data = jit_data;
 	}
 	priv_stack_ptr = prog->aux->priv_stack_ptr;
 	if (!priv_stack_ptr && prog->aux->jits_use_priv_stack) {
 		/* Allocate actual private stack size with verifier-calculated
 		 * stack size plus two memory guards to protect overflow and
 		 * underflow.
 		 */
 		priv_stack_alloc_sz = round_up(prog->aux->stack_depth, 16) +
 				      2 * PRIV_STACK_GUARD_SZ;
 		priv_stack_ptr = __alloc_percpu_gfp(priv_stack_alloc_sz, 16, GFP_KERNEL);
 		if (!priv_stack_ptr) {
 			prog = orig_prog;
 			goto out_priv_stack;
 		}

 		priv_stack_init_guard(priv_stack_ptr, priv_stack_alloc_sz);
 		prog->aux->priv_stack_ptr = priv_stack_ptr;
 	}
 	if (jit_data->ctx.offset) {
 		ctx = jit_data->ctx;
 		ro_image_ptr = jit_data->ro_image;
 		ro_header = jit_data->ro_header;
 		header = jit_data->header;
 		image_ptr = (void *)header + ((void *)ro_image_ptr
 						 - (void *)ro_header);
 		extra_pass = true;
 		prog_size = sizeof(u32) * ctx.idx;
 		goto skip_init_ctx;
 	}
 	memset(&ctx, 0, sizeof(ctx));
 	ctx.prog = prog;

 	ctx.offset = kvzalloc_objs(int, prog->len + 1);
 	if (ctx.offset == NULL) {
 		prog = orig_prog;
 		goto out_off;
 	}

 	ctx.user_vm_start = bpf_arena_get_user_vm_start(prog->aux->arena);
 	ctx.arena_vm_start = bpf_arena_get_kern_vm_start(prog->aux->arena);

 	if (priv_stack_ptr)
 		ctx.priv_sp_used = true;

 	/* Pass 1: Estimate the maximum image size.
 	 *
 	 * BPF line info needs ctx->offset[i] to be the offset of
 	 * instruction[i] in jited image, so build prologue first.
 	 */
 	if (build_prologue(&ctx, was_classic)) {
 		prog = orig_prog;
 		goto out_off;
 	}

 	if (build_body(&ctx, extra_pass)) {
 		prog = orig_prog;
 		goto out_off;
 	}

 	ctx.epilogue_offset = ctx.idx;
 	build_epilogue(&ctx, was_classic);
 	build_plt(&ctx);

 	extable_align = __alignof__(struct exception_table_entry);
 	extable_size = prog->aux->num_exentries *
 		sizeof(struct exception_table_entry);

 	/* Now we know the maximum image size. */
 	prog_size = sizeof(u32) * ctx.idx;
 	/* also allocate space for plt target */
 	extable_offset = round_up(prog_size + PLT_TARGET_SIZE, extable_align);
 	image_size = extable_offset + extable_size;
 	ro_header = bpf_jit_binary_pack_alloc(image_size, &ro_image_ptr,
-					      sizeof(u32), &header, &image_ptr,
+					      sizeof(u64), &header, &image_ptr,
 					      jit_fill_hole);
 	if (!ro_header) {
 		prog = orig_prog;
 		goto out_off;
 	}

 	/* Pass 2: Determine jited position and result for each instruction */

 	/*
 	 * Use the image(RW) for writing the JITed instructions. But also save
 	 * the ro_image(RX) for calculating the offsets in the image. The RW
 	 * image will be later copied to the RX image from where the program
 	 * will run. The bpf_jit_binary_pack_finalize() will do this copy in the
 	 * final step.
 	 */
 	ctx.image = (__le32 *)image_ptr;
 	ctx.ro_image = (__le32 *)ro_image_ptr;
 	if (extable_size)
 		prog->aux->extable = (void *)ro_image_ptr + extable_offset;
 skip_init_ctx:
 	ctx.idx = 0;
 	ctx.exentry_idx = 0;
 	ctx.write = true;

 	build_prologue(&ctx, was_classic);

 	/* Record exentry_idx and body_idx before first build_body */
 	exentry_idx = ctx.exentry_idx;
 	body_idx = ctx.idx;
 	/* Dont write body instructions to memory for now */
 	ctx.write = false;

 	if (build_body(&ctx, extra_pass)) {
 		prog = orig_prog;
 		goto out_free_hdr;
 	}

 	ctx.epilogue_offset = ctx.idx;
 	ctx.exentry_idx = exentry_idx;
 	ctx.idx = body_idx;
 	ctx.write = true;

 	/* Pass 3: Adjust jump offset and write final image */
 	if (build_body(&ctx, extra_pass) ||
 		WARN_ON_ONCE(ctx.idx != ctx.epilogue_offset)) {
 		prog = orig_prog;
 		goto out_free_hdr;
 	}

 	build_epilogue(&ctx, was_classic);
 	build_plt(&ctx);

 	/* Extra pass to validate JITed code. */
 	if (validate_ctx(&ctx)) {
 		prog = orig_prog;
 		goto out_free_hdr;
 	}

 	/* update the real prog size */
 	prog_size = sizeof(u32) * ctx.idx;

 	/* And we're done. */
 	if (bpf_jit_enable > 1)
 		bpf_jit_dump(prog->len, prog_size, 2, ctx.image);

 	if (!prog->is_func || extra_pass) {
 		/* The jited image may shrink since the jited result for
 		 * BPF_CALL to subprog may be changed from indirect call
 		 * to direct call.
 		 */
 		if (extra_pass && ctx.idx > jit_data->ctx.idx) {
 			pr_err_once("multi-func JIT bug %d > %d\n",
 				    ctx.idx, jit_data->ctx.idx);
 			prog->bpf_func = NULL;
 			prog->jited = 0;
 			prog->jited_len = 0;
 			goto out_free_hdr;
 		}
 		if (WARN_ON(bpf_jit_binary_pack_finalize(ro_header, header))) {
 			/* ro_header has been freed */
 			ro_header = NULL;
 			prog = orig_prog;
 			goto out_off;
 		}
 		/*
 		 * The instructions have now been copied to the ROX region from
 		 * where they will execute. Now the data cache has to be cleaned to
 		 * the PoU and the I-cache has to be invalidated for the VAs.
 		 */
 		bpf_flush_icache(ro_header, ctx.ro_image + ctx.idx);
 	} else {
 		jit_data->ctx = ctx;
 		jit_data->ro_image = ro_image_ptr;
 		jit_data->header = header;
 		jit_data->ro_header = ro_header;
 	}

 	prog->bpf_func = (void *)ctx.ro_image + cfi_get_offset();
 	prog->jited = 1;
 	prog->jited_len = prog_size - cfi_get_offset();

 	if (!prog->is_func || extra_pass) {
 		int i;

 		/* offset[prog->len] is the size of program */
 		for (i = 0; i <= prog->len; i++)
 			ctx.offset[i] *= AARCH64_INSN_SIZE;
 		bpf_prog_fill_jited_linfo(prog, ctx.offset + 1);
 		/*
 		 * The bpf_prog_update_insn_ptrs function expects offsets to
 		 * point to the first byte of the jitted instruction (unlike
 		 * the bpf_prog_fill_jited_linfo above, which, for historical
 		 * reasons, expects to point to the next instruction)
 		 */
 		bpf_prog_update_insn_ptrs(prog, ctx.offset, ctx.ro_image);
 out_off:
 		if (!ro_header && priv_stack_ptr) {
 			free_percpu(priv_stack_ptr);
 			prog->aux->priv_stack_ptr = NULL;
 		}
 		kvfree(ctx.offset);
 out_priv_stack:
 		kfree(jit_data);
 		prog->aux->jit_data = NULL;
 	}
 out:
 	if (tmp_blinded)
 		bpf_jit_prog_release_other(prog, prog == orig_prog ?
 					   tmp : orig_prog);
 	return prog;

 out_free_hdr:
 	if (header) {
 		bpf_arch_text_copy(&ro_header->size, &header->size,
 				   sizeof(header->size));
 		bpf_jit_binary_pack_free(ro_header, header);
 	}
 	goto out_off;
 }



